async function gerarNecessidadesUniformes() {
  const container = document.getElementById('resultadoOrcamentoUniformes');
  container.classList.remove('hidden');
  container.innerHTML = '<div class="text-center py-8 text-slate-500"><i class="fa-solid fa-spinner fa-spin mr-2"></i> Calculando necessidades e orÃ§amentos...</div>';
  
  try {
    const res = await fetch('/api/uniformes/gerar-necessidades');
    const necessidades = await res.json();
    
    // Group by Fornecedor
    const porFornecedor = {};
    
    necessidades.forEach(n => {
      const fName = n.fornecedor_nome;
      if(!porFornecedor[fName]) {
        porFornecedor[fName] = { itens: {}, total_fornecedor: 0 };
      }
      
      const key = `${n.item} - Tam: ${n.tamanho}`;
      if(!porFornecedor[fName].itens[key]) {
        porFornecedor[fName].itens[key] = {
          item: n.item,
          tamanho: n.tamanho,
          quantidade: 0,
          valor_unitario: n.valor_unitario,
          valor_total: 0
        };
      }
      porFornecedor[fName].itens[key].quantidade += n.quantidade;
      const subtotal = n.quantidade * n.valor_unitario;
      porFornecedor[fName].itens[key].valor_total += subtotal;
      porFornecedor[fName].total_fornecedor += subtotal;
    });
    
    let html = '';
    let totalGeral = 0;
    
    for (const [forn, dados] of Object.entries(porFornecedor)) {
      totalGeral += dados.total_fornecedor;
      
      html += `
        <div class="border border-slate-200 rounded-lg overflow-hidden mb-6">
          <div class="bg-slate-800 text-white px-4 py-3 flex justify-between items-center">
            <h4 class="font-bold"><i class="fa-solid fa-building mr-2"></i> ${forn}</h4>
            <span class="font-black text-emerald-400">Total: R$ ${dados.total_fornecedor.toFixed(2).replace('.', ',')}</span>
          </div>
          <table class="w-full text-left text-sm whitespace-nowrap">
            <thead class="bg-slate-100 text-slate-600">
              <tr>
              <th class="px-4 py-2">PeÃ§a</th>
              <th class="px-4 py-2">Tamanho</th>
              <th class="px-4 py-2 text-center" title="Quantidade solicitada na planilha">Qtd Req.</th>
              <th class="px-4 py-2 text-center" title="Quantidade para o estoque">Adicional</th>
              <th class="px-4 py-2 text-center" title="Soma total do pedido">Qtd Final</th>
              <th class="px-4 py-2 text-right">Val. UnitÃ¡rio</th>
              <th class="px-4 py-2 text-right">Subtotal</th>
            </tr>
            </thead>
            <tbody class="divide-y divide-slate-100">
              ${Object.values(dados.itens).sort((a,b) => a.item.localeCompare(b.item)).map(i => `
                <tr class="orcamento-linha" data-vu="${i.valor_unitario}" data-fornecedor="${forn}">
                <td class="px-4 py-2 font-medium td-peca">${i.item}</td>
                <td class="px-4 py-2 td-tamanho"><span class="bg-indigo-100 text-indigo-800 text-xs px-2 py-0.5 rounded">${i.tamanho}</span></td>
                <td class="px-4 py-2 text-center text-slate-500 text-xs td-req" data-val="${i.quantidade}">${i.quantidade}</td>
                <td class="px-4 py-2 text-center">
                   <input type="number" min="0" value="0" class="w-16 text-center text-sm border border-slate-300 rounded p-0.5 font-bold text-indigo-700 td-adicional focus:outline-none focus:ring-2 focus:ring-indigo-500" oninput="atualizarLinhaOrcamentoUniformes(this)" />
                </td>
                <td class="px-4 py-2 text-center font-bold text-slate-900 text-[15px] td-final">${i.quantidade}</td>
                <td class="px-4 py-2 text-right text-xs text-slate-500 td-vu">R$ ${i.valor_unitario.toFixed(2).replace('.', ',')}</td>
                <td class="px-4 py-2 text-right font-black text-slate-700 td-subtotal" data-subtotal="${i.valor_total}">R$ ${i.valor_total.toFixed(2).replace('.', ',')}</td>
                </tr>
              `).join('')}
            </tbody>
          </table>
        </div>
      `;
    }
    
    if(Object.keys(porFornecedor).length === 0) {
      container.innerHTML = '<div class="text-center py-8 text-slate-500">Nenhum item necessÃ¡rio.</div>';
    } else {
      container.innerHTML = html + `
        <div class="bg-emerald-50 border border-emerald-200 rounded-lg p-5 flex justify-between items-center mt-6">
          <div class="text-emerald-800 uppercase font-bold tracking-wider">Custo Total de Uniformes</div>
          <div class="text-3xl font-black text-emerald-700">R$ ${totalGeral.toFixed(2).replace('.', ',')}</div>
        </div>
      `;
    }
    
  } catch(e) { console.error(e); }
}

