    { 'FUNCAO': 'SUPERVISOR', 'GENERO': 'TODOS', 'PECA': 'JAQUETA IMPERMEÃVEL', 'QUANTIDADE': 1, 'PRECO': 120.00, 'FORNECEDOR': 'UNIFORMES LTDA' }
