function inicializarCompetenciaFaltas() {
   const input = document.getElementById('filtroFaltasMes');
   if (!input.value) {
      const hoje = new Date();
      const ano = hoje.getFullYear();
      const mes = String(hoje.getMonth() + 1).padStart(2, '0');
      input.value = `${ano}-${mes}`;
   }
   carregarFaltasCompetencia();
}

async function carregarFaltasCompetencia() {
   const comp = document.getElementById('filtroFaltasMes').value;
   if (!comp) return;
   
   try {
      const res = await fetch(`/api/fechamento-mensal/status?ano_mes=${comp}`);
      const data = await res.json();
      
      const badge = document.getElementById('statusFechamentoBadge');
      const btnFechar = document.getElementById('btnFecharMes');
      const btnNovaFalta = document.querySelector('button[onclick="abrirModalNovaFalta()"]');
      
      if (data.fechado) {
         badge.classList.remove('hidden');
         badge.classList.add('flex');
         btnFechar.classList.add('hidden');
         if(btnNovaFalta) btnNovaFalta.classList.add('hidden'); // Impede novas faltas no mÃªs fechado
      } else {
         badge.classList.add('hidden');
         badge.classList.remove('flex');
         btnFechar.classList.remove('hidden');
         if(btnNovaFalta) btnNovaFalta.classList.remove('hidden');
      }
      
      // O carregarFaltas() original lÃª direto do filtroFaltasMes, entÃ£o sÃ³ chamamos.
      carregarFaltas(); 
   } catch(e) {
      console.error(e);
   }
}

async function fecharCompetenciaMensal() {
   const comp = document.getElementById('filtroFaltasMes').value;
   if (!comp) return;
   
   if(!confirm('Tem certeza que deseja FECHAR O MÃŠS ' + comp + '\n\nIsso congelarÃ¡ os apontamentos e impedirÃ¡ alteraÃ§Ãµes retroativas!')) return;
   
   const totalFaltas = document.getElementById('kpiFaltasTotal').innerText;
   const custoCoberturas = 0; // Pode ser calculado depois com kpiFinanceiroCoberturas
   const resp = state.usuarioLogado ? state.usuarioLogado.nome : 'Admin';
   
   try {
      const res = await fetch('/api/fechamento-mensal', {
         method: 'POST',
         headers: { 'Content-Type': 'application/json' },
         body: JSON.stringify({ ano_mes: comp, total_faltas: parseInt(totalFaltas) || 0, custo_coberturas: custoCoberturas, responsavel: resp })
      });
      const data = await res.json();
      if(data.success) {
         alert(data.message);
         carregarFaltasCompetencia();
      } else {
         alert('Erro: ' + data.message);
      }
   } catch(e) {
      alert('Erro de rede');
   }
}


function renderizarConsolidadoCompras(modo) {
   const btnF = document.getElementById('btnConsolidadoFornecedor');
   const btnC = document.getElementById('btnConsolidadoCliente');
   
   if (modo === 'fornecedor') {
      btnF.classList.add('bg-white', 'text-slate-800', 'shadow-sm');
      btnF.classList.remove('text-slate-500');
      btnC.classList.add('text-slate-500');
      btnC.classList.remove('bg-white', 'text-slate-800', 'shadow-sm');
      
      // LÃ³gica de agrupar por fornecedor...
      // (Atualiza a tabela id="tabelaConsolidadaBody")
   } else {
      btnC.classList.add('bg-white', 'text-slate-800', 'shadow-sm');
      btnC.classList.remove('text-slate-500');
      btnF.classList.add('text-slate-500');
      btnF.classList.remove('bg-white', 'text-slate-800', 'shadow-sm');
      
      // LÃ³gica de agrupar por cliente/posto...
   }
}





function alternarTodosClientes(master) {
   document.querySelectorAll('.chk-cliente').forEach(chk => chk.checked = master.checked);
   atualizarBarraAcoesClientes();
}
function atualizarBarraAcoesClientes() {
   const marcados = document.querySelectorAll('.chk-cliente:checked');
   const barra = document.getElementById('barraAcoesClientes');
   if(barra) {
      if(marcados.length > 0) {
         barra.classList.remove('hidden');
         barra.classList.add('flex');
         document.getElementById('qtdClientesSelecionados').innerText = marcados.length;
      } else {
         barra.classList.add('hidden');
         barra.classList.remove('flex');
      }
   }
}
async function excluirClientesSelecionados() {
   const marcados = document.querySelectorAll('.chk-cliente:checked');
   if(marcados.length === 0) return;
   if(!confirm('AtenÃ§Ã£o: Deseja excluir ' + marcados.length + ' cliente(s) e todos os postos vinculados a ele?')) return;
   
   const ids = Array.from(marcados).map(c => c.value);
   try {
      const res = await fetch('/api/batch-delete', {
         method: 'POST',
         headers: {'Content-Type': 'application/json'},
         body: JSON.stringify({ entidade: 'clientes', ids })
      });
      const data = await res.json();
      if(data.success) {
         carregarClientes();
      } else {
         alert(data.message);
      }
   } catch(e) {
      alert('Erro ao excluir clientes');
   }
}
   

function moverCardSst(btn, direcao) {
   const card = btn.closest('.bg-white.p-3');
   const currentContainer = card.parentElement;
   let targetContainerId = '';
   
   if(currentContainer.id === 'kbSstAguardandoLista') {
      if(direcao === 'right') targetContainerId = 'kbSstIntegrandoLista';
   } else if (currentContainer.id === 'kbSstIntegrandoLista') {
      if(direcao === 'left') targetContainerId = 'kbSstAguardandoLista';
      if(direcao === 'right') targetContainerId = 'kbSstLiberadoLista';
   } else if (currentContainer.id === 'kbSstLiberadoLista') {
      if(direcao === 'left') targetContainerId = 'kbSstIntegrandoLista';
   }
   
   if(targetContainerId) {
      document.getElementById(targetContainerId).appendChild(card);
      atualizarSetasSst(card, targetContainerId);
      atualizarContadoresSst();
   }
}

function atualizarSetasSst(card, newContainerId) {
   const botoesContainer = card.querySelector('.flex.items-center.gap-2');
   if(!botoesContainer) return;
   
   let btns = '';
   if(newContainerId === 'kbSstAguardandoLista') {
      btns = `<button type="button" onclick="moverCardSst(this, 'right')" class="text-xs text-amber-600 hover:text-amber-800"><i class="fa-solid fa-arrow-right"></i></button>`;
   } else if (newContainerId === 'kbSstIntegrandoLista') {
      btns = `<button type="button" onclick="moverCardSst(this, 'left')" class="text-xs text-slate-500 hover:text-slate-700 mr-2"><i class="fa-solid fa-arrow-left"></i></button>
              <button type="button" onclick="moverCardSst(this, 'right')" class="text-xs text-emerald-600 hover:text-emerald-800"><i class="fa-solid fa-arrow-right"></i></button>`;
   } else if (newContainerId === 'kbSstLiberadoLista') {
      btns = `<button type="button" onclick="moverCardSst(this, 'left')" class="text-xs text-amber-500 hover:text-amber-700"><i class="fa-solid fa-arrow-left"></i></button>`;
   }
   botoesContainer.innerHTML = btns;
}

function atualizarContadoresSst() {
   const c1 = document.getElementById('kbSstAguardandoLista').children.length;
   const c2 = document.getElementById('kbSstIntegrandoLista').children.length;
   const c3 = document.getElementById('kbSstLiberadoLista').children.length;
   
   document.getElementById('kbSstAguardandoTotal').innerText = c1;
   document.getElementById('kbSstIntegrandoTotal').innerText = c2;
   document.getElementById('kbSstLiberadoTotal').innerText = c3;
   
   const total = c1 + c2 + c3;
   const p = total > 0 ? Math.round((c3 / total) * 100) : 0;
   
   document.getElementById('kpiSstAdmissoes').innerText = total;
   document.getElementById('kpiSstIntegrados').innerText = c3;
   document.getElementById('kpiSstConformidade').innerText = p + '%';
}


function arquivarCardSst(btn) {
   if(!confirm('Deseja arquivar este processo de integraÃ§Ã£o? O colaborador sairÃ¡ do painel de admissÃµes deste mÃªs.')) return;
   const card = btn.closest('.bg-white.p-3');
   if(card) {
      card.remove();
      atualizarContadoresSst();
   }
}

